using System;
using System.Linq;
using NUnit.Framework;
using Unity.Collections;
using Unity.Netcode;
using UnityEngine;
namespace Wildfolk.Tests
{
    public sealed class FoodModelTests
    {
        private ContentCatalog C=>Resources.Load<SaveGameRules>("SaveGameRules").Catalog;
        [Test]public void OneMealReplacesInsteadOfStackingAndSameMealResetsOnlyItsDuration()
        {var m=new MealModel();m.Begin(C.Item("hunters_stew"));Assert.That(m.Bonus(MealEffect.MaximumHealth),Is.EqualTo(8));m.Advance(20);m.Begin(C.Item("hunters_stew"));Assert.That(m.Remaining,Is.EqualTo(150));Assert.That(m.Bonus(MealEffect.MaximumHealth),Is.EqualTo(8));m.Begin(C.Item("forager_soup"));Assert.That(m.Bonus(MealEffect.MaximumHealth),Is.Zero);Assert.That(m.Bonus(MealEffect.NaturalRecovery),Is.EqualTo(.15f));m.Begin(C.Item("trail_broth"));Assert.That(m.Bonus(MealEffect.NaturalRecovery),Is.Zero);Assert.That(m.Bonus(MealEffect.StaminaRecovery),Is.EqualTo(.10f));Assert.That(m.Advance(150),Is.True);Assert.That(m.Item,Is.Null);Assert.That(m.Bonus(MealEffect.StaminaRecovery),Is.Zero);Assert.That(m.Advance(20),Is.False);Assert.Throws<ArgumentOutOfRangeException>(()=>m.Advance(float.NaN));Assert.Throws<ArgumentException>(()=>m.Begin(C.Item("bone_broth")));}
        [Test]public void MealsAreThreeDistinctPotChoicesAndExistingRecoveryFoodsRemainImmediate()
        {var ids=new[]{"hunters_stew","forager_soup","trail_broth"};Assert.That(C.Items.Length,Is.EqualTo(126));Assert.That(C.Recipes.Length,Is.EqualTo(103));Assert.That(C.Items.Count(i=>i.Consumable?.Meal!=null),Is.EqualTo(3));foreach(var id in ids){var food=C.Item(id).Consumable;Assert.That(food.Kind,Is.EqualTo(ConsumableKind.Food));Assert.That(food.HealthRestore+food.GradualHealthRestore+food.StaminaRestore,Is.Zero);Assert.That(food.Meal.Duration,Is.EqualTo(150));Assert.That(food.UseCooldownSeconds,Is.EqualTo(4));Assert.That(C.Recipe(id).RequiredStation,Is.EqualTo(StationKind.CookingPot));Assert.That(C.Recipe(id).ProcessingSeconds,Is.EqualTo(10));}Assert.That(C.Recipe(ids[0]).Ingredients.Select(i=>i.Item.Id+":"+i.Count),Is.EquivalentTo(new[]{"raw_meat:2","bone:1","mushroom:1","berry:1"}));Assert.That(C.Recipe(ids[1]).Ingredients.Select(i=>i.Item.Id+":"+i.Count),Is.EquivalentTo(new[]{"medicinal_herb:1","mushroom:2","berry:1"}));Assert.That(C.Recipe(ids[2]).Ingredients.Select(i=>i.Item.Id+":"+i.Count),Is.EquivalentTo(new[]{"raw_fish:1","medicinal_herb:1","berry:2"}));Assert.That(C.Item("bone_broth").Consumable.HealthRestore,Is.EqualTo(18));Assert.That(C.Item("restorative_broth").Consumable.StaminaRestore,Is.EqualTo(35));Assert.That(C.Item("trail_ration").Consumable.StaminaRestore,Is.EqualTo(20));foreach(var id in new[]{"bone_broth","restorative_broth","trail_ration","mixed_stew","healing_salve","field_dressing"})Assert.That(C.Item(id).Consumable.Meal,Is.Null);Assert.That(C.Recipes.Count(r=>r.RequiredStation==StationKind.CookingPot),Is.EqualTo(9));Assert.That(C.Recipes.Count(r=>r.RequiredStation==StationKind.Campfire),Is.EqualTo(6));}
        [Test]public void StewsHavePlantHydrationMeatHungerFishHydrationAndMixedNutritionRoles()
        {Assert.That(C.Item("meat_stew").Consumable.HungerRestore,Is.EqualTo(52));Assert.That(C.Item("fish_stew").Consumable.ThirstRestore,Is.EqualTo(26));Assert.That(C.Item("mushroom_stew").Consumable.ThirstRestore,Is.EqualTo(18));Assert.That(C.Item("mixed_stew").Consumable.HealthRestore,Is.EqualTo(8));Assert.That(C.Item("healing_salve").Consumable.HealthRestore,Is.EqualTo(30));Assert.That(C.Item("field_dressing").Consumable.GradualHealthRestore,Is.EqualTo(20));Assert.That(Resources.Load<SaveGameRules>("SaveGameRules").World.Resources.Length,Is.EqualTo(13));}
        [Test]public void StaminaMealChangesRateWithoutChangingDelayCostOrMaximum()
        {var d=Resources.Load<SaveGameRules>("SaveGameRules").Player.GetComponent<PlayerLocomotion>().Definition;var normal=new StaminaModel(d);var meal=new StaminaModel(d);normal.Restore(0,d.RecoveryDelay);meal.Restore(0,d.RecoveryDelay);normal.Advance(1,0,true,1,1,1);meal.Advance(1,0,true,1,1,1.1f);Assert.That(normal.Current+meal.Current,Is.Zero);Assert.That(meal.RecoveryWait,Is.EqualTo(normal.RecoveryWait));normal.Advance(2,0,true,1,1,1);meal.Advance(2,0,true,1,1,1.1f);Assert.That(meal.Current,Is.EqualTo(normal.Current*1.1f).Within(.001f));Assert.That(meal.Maximum,Is.EqualTo(normal.Maximum));Assert.That(d.DashCost,Is.EqualTo(24));Assert.That(d.SprintDrain,Is.EqualTo(14));Assert.That(d.RecoveryDelay,Is.EqualTo(1.2f));}
        [Test]public void NetworkMealIdentityAndEndTimeRoundTripAndParticipateInEquality()
        {var a=new PlayerStatusState{HP=104,MaximumHP=108,MealItem=123,MealUntil=500.125,TreatmentUntil=358.75};using(var w=new FastBufferWriter(128,Allocator.Temp)){w.WriteNetworkSerializable(a);using(var r=new FastBufferReader(w,Allocator.Temp)){r.ReadNetworkSerializable(out PlayerStatusState b);Assert.That(b.Equals(a),Is.True);b.MealItem=124;Assert.That(b.Equals(a),Is.False);b=a;b.MealUntil++;Assert.That(b.Equals(a),Is.False);}}Assert.That(NetworkProtocol.Current,Is.EqualTo(15));}
        [Test]public void HostCanExpireWaterPenaltyWithoutEnablingNutritionDrain()
        {var d=Resources.Load<SaveGameRules>("SaveGameRules").Player.GetComponent<PlayerSurvival>().Definition;var m=new SurvivalModel(d);m.SetMeters(80,80);m.Restore(C.Item("raw_water_cup").Consumable);var thirst=m.Thirst;m.AdvanceEffects(59);Assert.That(m.RecoveryBlockRemaining,Is.EqualTo(1));Assert.That(m.Hunger,Is.EqualTo(80));Assert.That(m.Thirst,Is.EqualTo(thirst));m.AdvanceEffects(2);Assert.That(m.RecoveryBlockRemaining,Is.Zero);Assert.That(m.DrainPenaltyRemaining,Is.Zero);Assert.That(m.DrainMultiplier,Is.EqualTo(1));Assert.Throws<ArgumentOutOfRangeException>(()=>m.AdvanceEffects(float.NaN));}
    }
}
